  /\bEAA[A-Za-z0-9]{20,}\b/g, // Meta / WhatsApp access tokens
  /\bAIza[0-9A-Za-z_-]{30,}\b/g, // Google API keys
  /\bya29\.[0-9A-Za-z_-]{20,}\b/g, // Google OAuth access tokens
