function assertTransition(from, to) {
  if (!STATUSES.includes(to)) throw new Error(`UNKNOWN_STATUS: ${to}`);
  if (!canTransition(from, to)) throw new Error(`INVALID_TRANSITION: ${from} -> ${to}`);
