      const candidate = path.concat(next);
      if (next === to) return candidate;
      seen.add(next);
      queue.push(candidate);
    }
  }
  return null;
}

module.exports = {
  STATUSES,
  TRANSITIONS,
  TERMINAL,
  MERGEABLE,
  AWAITING_REPLY,
  NO_FOLLOWUP,
  LABELS,
  canTransition,
  assertTransition,
  pathBetween,
};

